public enum DailyQuotesCatalog {
    public static let verses: [OfflineDailyVerse] = [
        OfflineDailyVerse(surahNumber: 1, ayahNumber: 2, textAr: "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", meaningEn: "All praise is due to Allah, Lord of the worlds.", meaningTr: "Hamd, âlemlerin Rabbi Allah'a mahsustur.", meaningUr: "سب تعریفیں اللہ کے لیے ہیں جو تمام جہانوں کا رب ہے۔", surahNameAr: "الفاتحة", surahNameEn: "Al-Fatihah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 152, textAr: "فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ", meaningEn: "So remember Me; I will remember you. And be grateful to Me and do not deny Me.", meaningTr: "Öyleyse beni anın ki ben de sizi anayım. Bana şükredin, sakın nankörlük etmeyin.", meaningUr: "پس تم مجھے یاد رکھو میں تمہیں یاد رکھوں گا، اور میرا شکر ادا کرو اور ناشکری نہ کرو۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 186, textAr: "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ", meaningEn: "And when My servants ask you concerning Me, indeed I am near. I respond to the invocation of the supplicant when he calls upon Me.", meaningTr: "Kullarım sana beni sorduğunda bilsinler ki ben şüphesiz onlara yakınım. Bana dua ettiğinde dua edenin dileğine karşılık veririm.", meaningUr: "اور جب میرے بندے آپ سے میرے متعلق پوچھیں تو بیشک میں قریب ہوں، دعا کرنے والے کی دعا قبول کرتا ہوں جب وہ مجھے پکارتا ہے۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 2, ayahNumber: 286, textAr: "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا", meaningEn: "Allah does not charge a soul except with that within its capacity.", meaningTr: "Allah hiçbir kimseye gücünün yeteceğinden fazlasını yüklemez.", meaningUr: "اللہ کسی جان پر اس کی طاقت سے بڑھ کر بوجھ نہیں ڈالتا۔", surahNameAr: "البقرة", surahNameEn: "Al-Baqarah"),
        OfflineDailyVerse(surahNumber: 3, ayahNumber: 139, textAr: "وَلَا تَهِنُوا وَلَا تَحْزَنُوا وَأَنتُمُ الْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ", meaningEn: "So do not weaken and do not grieve, and you will be superior if you are believers.", meaningTr: "Gevşeklik göstermeyin, üzülmeyin; eğer inanmışsanız şüphesiz en üstün olan sizsiniz.", meaningUr: "اور کمزور نہ پڑو اور غم نہ کرو، اور تم ہی غالب رہو گے اگر تم مومن ہو۔", surahNameAr: "آل عمران", surahNameEn: "Ali 'Imran"),
        OfflineDailyVerse(surahNumber: 13, ayahNumber: 28, textAr: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ", meaningEn: "Unquestionably, by the remembrance of Allah hearts are assured.", meaningTr: "Bilesiniz ki kalpler ancak Allah'ı anmakla huzur bulur.", meaningUr: "خبردار! اللہ کے ذکر ہی سے دلوں کو اطمینان نصیب ہوتا ہے۔", surahNameAr: "الرعد", surahNameEn: "Ar-Ra'd"),
        OfflineDailyVerse(surahNumber: 14, ayahNumber: 7, textAr: "لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ", meaningEn: "If you are grateful, I will surely increase you in favor.", meaningTr: "Eğer şükrederseniz elbette size nimetimi artırırım.", meaningUr: "اگر تم شکر کرو گے تو میں تمہیں ضرور زیادہ دوں گا۔", surahNameAr: "إبراهيم", surahNameEn: "Ibrahim"),
        OfflineDailyVerse(surahNumber: 29, ayahNumber: 69, textAr: "وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ۚ وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ", meaningEn: "And those who strive for Us — We will surely guide them to Our ways. And indeed, Allah is with the doers of good.", meaningTr: "Bizim uğrumuzda cihad edenlere gelince, elbette onları bize ulaşan yollara iletiriz. Şüphesiz Allah iyilik edenlerle beraberdir.", meaningUr: "اور جن لوگوں نے ہماری راہ میں کوشش کی، ہم انہیں ضرور اپنے راستے دکھا دیں گے، اور بیشک اللہ نیکی کرنے والوں کے ساتھ ہے۔", surahNameAr: "العنكبوت", surahNameEn: "Al-'Ankabut"),
        OfflineDailyVerse(surahNumber: 39, ayahNumber: 53, textAr: "لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا", meaningEn: "Do not despair of the mercy of Allah. Indeed, Allah forgives all sins.", meaningTr: "Allah'ın rahmetinden ümit kesmeyin. Şüphesiz Allah bütün günahları bağışlar.", meaningUr: "اللہ کی رحمت سے ناامید نہ ہو، بیشک اللہ تمام گناہ بخش دیتا ہے۔", surahNameAr: "الزمر", surahNameEn: "Az-Zumar"),
        OfflineDailyVerse(surahNumber: 65, ayahNumber: 3, textAr: "وَمَن يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ", meaningEn: "And whoever relies upon Allah — then He is sufficient for him.", meaningTr: "Kim Allah'a tevekkül ederse O, ona yeter.", meaningUr: "اور جو اللہ پر بھروسہ کرے تو وہ اس کے لیے کافی ہے۔", surahNameAr: "الطلاق", surahNameEn: "At-Talaq"),
        OfflineDailyVerse(surahNumber: 94, ayahNumber: 5, textAr: "فَإِنَّ مَعَ الْعُسْرِ يُسْرًا", meaningEn: "For indeed, with hardship comes ease.", meaningTr: "Şüphesiz güçlükle beraber bir kolaylık vardır.", meaningUr: "پس بیشک مشکل کے ساتھ آسانی ہے۔", surahNameAr: "الشرح", surahNameEn: "Ash-Sharh"),
        OfflineDailyVerse(surahNumber: 94, ayahNumber: 6, textAr: "إِنَّ مَعَ الْعُسْرِ يُسْرًا", meaningEn: "Indeed, with hardship comes ease.", meaningTr: "Gerçekten güçlükle beraber bir kolaylık vardır.", meaningUr: "بیشک مشکل کے ساتھ آسانی ہے۔", surahNameAr: "الشرح", surahNameEn: "Ash-Sharh"),
    ]

    public static let hadiths: [OfflineDailyHadith] = [
        OfflineDailyHadith(id: "1", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أمير المؤمنين عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح البخاري وصحيح مسلم - الحديث الأول من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 1 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "هذا الحديث أصل عظيم من أصول الدين وقاعدة تدور عليها جميع الأعمال، فالنية الصادقة شرط لقبول كل عبادة وقربة.", explanationEn: "A foundational principle of Islam: all deeds are evaluated by sincerity and the underlying intention."),
        OfflineDailyHadith(id: "2", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن عمر بن الخطاب رضي الله عنه", narratorEn: "Narrated by Umar ibn al-Khattab (RA)", referenceAr: "صحيح مسلم - الحديث الثاني من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 2 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "يُعرف هذا الحديث بأم السنة لاشتماله على جميع مراتب الدين الثلاث: ظاهر الإسلام، وباطن الإيمان، وغاية المراقبة في الإحسان.", explanationEn: "Encompasses the three levels of Islam: outward acts of devotion, inner faith, and the height of God-consciousness."),
        OfflineDailyHadith(id: "3", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 3 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "شبه النبي صلى الله عليه وسلم الإسلام بالبنيان المحكم، وأركانه الخمسة هي الأعمدة التي يقوم عليها.", explanationEn: "Metaphor of a sturdy building supported by its five structural pillars."),
        OfflineDailyHadith(id: "4", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أم المؤمنين عائشة رضي الله عنها", narratorEn: "Narrated by Aisha (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الخامس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 5 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "ميزان الأعمال الظاهرة، فكما أن حديث النيات ميزان الباطن، فهذا الحديث ميزان مطابقة العمل لشرع الله وسنة نبيه.", explanationEn: "The benchmark for external actions: any deed not adhering to the Quran and authentic Sunnah is rejected."),
        OfflineDailyHadith(id: "5", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن النعمان بن بشير رضي الله عنه", narratorEn: "Narrated by An-Nu'man ibn Bashir (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث السادس من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 6 of An-Nawawi", categoryAr: "اتباع السنة", categoryEn: "Following the Sunnah", explanationAr: "قاعدة الورع وصلاح القلوب، فالابتعاد عن الشبهات صيانة لدين المسلم وسلامة لقلبه.", explanationEn: "The golden rule of pious precaution and heart purification: steering clear of ambiguity preserves faith and integrity."),
        OfflineDailyHadith(id: "6", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن تميم الداري رضي الله عنه", narratorEn: "Narrated by Tamim ad-Dari (RA)", referenceAr: "صحيح مسلم - الحديث السابع من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 7 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "النصيحة كلمة جامعة تعني إرادة الخير للمنصوح له والقيام بحقوقه بإخلاص وأمانة.", explanationEn: "Defines sincere goodwill and fulfilling duties toward Allah, His revelation, leaders, and fellow humanity."),
        OfflineDailyHadith(id: "7", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "سنن الترمذي وابن ماجه (حسن) - الحديث الثاني عشر من الأربعين النووية", referenceEn: "Sunan at-Tirmidhi & Sunan Ibn Majah (Hasan) - Hadith 12 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "حفظ الوقت واللسان والجوارح عما لا فائدة فيه في دين أو دنيا، وهو عنوان سلامة الصدر ورجاحة العقل.", explanationEn: "Advises investing time and energy into beneficial pursuits while abandoning meddling in trivia."),
        OfflineDailyHadith(id: "8", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "صحيح البخاري ومسلم - الحديث الثالث عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari & Sahih Muslim - Hadith 13 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "كمال الإيمان يقتضي سلامة القلب من الغل والحسد، وتمني الخير والنفع لكل مسلم كما يتمناه لنفسه.", explanationEn: "True faith demands eradicating malice and genuinely wishing goodness, guidance, and prosperity for others."),
        OfflineDailyHadith(id: "9", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث الخامس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 35 of An-Nawawi", categoryAr: "الجار والمجتمع", categoryEn: "Neighbours & Society", explanationAr: "حرمة المسلم أعظم عند الله من حرمة الكعبة، والاعتداء عليه بالقول أو الفعل من كبائر الذنوب.", explanationEn: "Proclaims the absolute sanctity of human life, dignity, property, and personal honor in Islamic ethics."),
        OfflineDailyHadith(id: "10", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري - الحديث السادس عشر من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 16 of An-Nawawi", categoryAr: "حسن الخلق", categoryEn: "Good Character", explanationAr: "الغضب جماع الشر، واجتنابه ومجاهدة النفس عند ثورانه مفتاح كل خير وبر وسلامة.", explanationEn: "Self-restraint in moments of fury prevents destruction and opens the doors of wisdom and mercy."),
        OfflineDailyHadith(id: "11", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح مسلم - الحديث السابع عشر من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 17 of An-Nawawi", categoryAr: "الرحمة والرفق", categoryEn: "Mercy & Gentleness", explanationAr: "الإسلام دين الرحمة الشاملة والإتقان في كل عمل حتى في موضع الذبح وإراحة الحيوان.", explanationEn: "Manifests Islamic mercy and professional excellence across every single domain of life."),
        OfflineDailyHadith(id: "12", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عباس رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Abbas (RA)", referenceAr: "سنن الترمذي - الحديث التاسع عشر من الأربعين النووية (صحيح)", referenceEn: "Sunan at-Tirmidhi - Hadith 19 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "وصية نبوية جامعة ترسى في القلب التوحيد الخالص، واليقين بالقضاء والقدر، والتوكل على الله وحده.", explanationEn: "Masterful instruction cultivating sincere reliance upon Allah and certainty in divine decree."),
        OfflineDailyHadith(id: "13", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن سفيان بن عبد الله الثقفي رضي الله عنه", narratorEn: "Narrated by Sufyan ibn Abdullah (RA)", referenceAr: "صحيح مسلم - الحديث الحادي والعشرون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 21 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "جمع النبي صلى الله عليه وسلم في كلمتين أصول الإيمان الظاهر والباطن، والثبات على طاعة الله حتى الممات.", explanationEn: "Concise wisdom condensing faith into sincere belief followed by lifelong perseverance."),
        OfflineDailyHadith(id: "14", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح مسلم - الحديث السادس والثلاثون من الأربعين النووية", referenceEn: "Sahih Muslim - Hadith 36 of An-Nawawi", categoryAr: "العلم", categoryEn: "Knowledge", explanationAr: "حديث عظيم في فضل قضاء حوائج الناس، والتفريج عن المكروبين، وطلب العلم الشرعي، ومجالس الذكر.", explanationEn: "Glorious incentive for helping neighbors, easing distress, seeking knowledge, and gathering in remembrance of Allah."),
        OfflineDailyHadith(id: "15", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه (حديث قدسي)", narratorEn: "Narrated by Abu Hurairah (RA) - Hadith Qudsi", referenceAr: "صحيح البخاري - الحديث الثامن والثلاثون من الأربعين النووية", referenceEn: "Sahih al-Bukhari - Hadith 38 of An-Nawawi", categoryAr: "الإيمان والنية", categoryEn: "Faith & Intention", explanationAr: "أشرف حديث في بيان منزلة أولياء الله الصالحين، وفضل المحافظة على الفرائض والإكثار من النوافل.", explanationEn: "Delineates how performing obligatory deeds followed by voluntary acts earns Allah's direct divine love and protection."),
        OfflineDailyHadith(id: "16", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم - باب فضل الذكر", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الذكر حياة القلوب والأرواح، فالغافل عن ذكر الله ميت وإن كان يمشي بين الأحياء، والذاكر حي القلب بنور ربه.", explanationEn: "Remembering Allah infuses true life into hearts; abandoning remembrance results in spiritual death despite physical vitality."),
        OfflineDailyHadith(id: "17", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن جابر بن عبد الله رضي الله عنهما", narratorEn: "Narrated by Jabir ibn Abdullah (RA)", referenceAr: "جامع الترمذي وسنن ابن ماجه (حسن)", referenceEn: "Jami at-Tirmidhi & Sunan Ibn Majah (Hasan)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "كلمة التوحيد أعظم كلمة قالها النبيون، والحمد اعتراف بالنعمة وثناء على المنعم سبحانه.", explanationEn: "The proclamation of Tawhid is the greatest statement uttered, while praising Allah is the pinnacle of gratitude and prayer."),
        OfflineDailyHadith(id: "18", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "صحيح البخاري ومسلم - خاتمة صحيح البخاري", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "من رحمة الله الواسعة بعباده أن جعل هذا الذكر اليسير في النطق يثقل موازين الحسنات يوم القيامة.", explanationEn: "Demonstrates Allah's boundless grace where lightweight words carry immense weight on the Scales of Eternity."),
        OfflineDailyHadith(id: "19", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن شداد بن أوس رضي الله عنه", narratorEn: "Narrated by Shaddad ibn Aws (RA)", referenceAr: "صحيح البخاري - أذكار الصباح والمساء", referenceEn: "Sahih al-Bukhari - Morning & Evening Dhikr", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "جامع للاعتراف بالربوبية والعبودية والنعمة والتقصير، ومن قاله موقناً به فمات في يومه أو ليلته دخل الجنة.", explanationEn: "Harmonizes acknowledgment of divine lordship, human servitude, gratitude for blessings, and contrite repentance."),
        OfflineDailyHadith(id: "20", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي موسى الأشعري رضي الله عنه", narratorEn: "Narrated by Abu Musa Al-Ash'ari (RA)", referenceAr: "صحيح البخاري ومسلم", referenceEn: "Sahih al-Bukhari & Sahih Muslim", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "التبرؤ من الحول والقوة وتفويض الأمر كله لله القوي العزيز، وهي ذخر عظيم لصاحبها في الجنة.", explanationEn: "Acknowledges that all ability and transformation belong exclusively to Allah, storing perpetual treasures in Paradise."),
        OfflineDailyHadith(id: "21", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن سعد بن أبي وقاص رضي الله عنه", narratorEn: "Narrated by Sa'd ibn Abi Waqqas (RA)", referenceAr: "سنن الترمذي ومستدرك الحاكم (صحيح) - باب دعاء الكرب", referenceEn: "Sunan at-Tirmidhi & Mustadrak al-Hakim (Sahih)", categoryAr: "الدعاء", categoryEn: "Supplication", explanationAr: "أعظم دعاء لكشف الشدائد وتفريج الكرب؛ جمع بين التوحيد والتنزيه والاعتراف بالذنب.", explanationEn: "The ultimate prayer for relief from agony and tribulation, unifying Monotheism, adoration, and humble contrition."),
        OfflineDailyHadith(id: "22", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن سمرة بن جندب رضي الله عنه", narratorEn: "Narrated by Samurah ibn Jundub (RA)", referenceAr: "صحيح مسلم - باب فضل التسبيح والتحميد", referenceEn: "Sahih Muslim - Chapter on Tasbih & Tahmid", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "هذه الكلمات الأربع هي الباقيات الصالحات وغراس الجنة، وأحب الذكر إلى الله بعد القرآن الكريم.", explanationEn: "These four phrases form the everlasting righteous deeds, seedlings of Paradise, and the dearest words to Allah."),
        OfflineDailyHadith(id: "23", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أنس بن مالك رضي الله عنه", narratorEn: "Narrated by Anas ibn Malik (RA)", referenceAr: "سنن النسائي ومسند أحمد (صحيح) - باب فضل الصلاة على النبي", referenceEn: "Sunan an-Nasa'i & Musnad Ahmad (Sahih)", categoryAr: "الذكر", categoryEn: "Remembrance", explanationAr: "الصلاة على النبي صلى الله عليه وسلم سبب لمغفرة الذنوب وكفاية الهموم ونيل شفاعته ورفعة الدرجات في الدنيا والآخرة.", explanationEn: "Supplicating blessings upon the Prophet grants relief from grief, forgiveness of sins, high ranks, and intercession."),
        OfflineDailyHadith(id: "101", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن أبي هريرة رضي الله عنه", narratorEn: "Narrated by Abu Hurairah (RA)", referenceAr: "رواه البخاري (٥٢٨)", referenceEn: "Sahih al-Bukhari 528", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
        OfflineDailyHadith(id: "102", textAr: "", translationEn: "", translationTr: "", translationUr: "", narratorAr: "عن عبد الله بن عمر رضي الله عنهما", narratorEn: "Narrated by Abdullah ibn Umar (RA)", referenceAr: "رواه البخاري (٦٤٥)", referenceEn: "Sahih al-Bukhari 645", categoryAr: "الصلاة", categoryEn: "Prayer", explanationAr: "", explanationEn: ""),
